use work_leaf::{PaneFocus, UiHarness};

#[test]
fn plain_v_yanks_right_pane_character_selection() {
    let mut harness = UiHarness::new(80, 24);
    harness.handle_bytes(&[23, b'"'"'l'"'"']);
    assert_eq!(harness.ui().focus(), PaneFocus::Right);

    harness.handle_byte(b'"'"'v'"'"');
    harness.handle_byte(b'"'"'l'"'"');
    harness.handle_byte(b'"'"'l'"'"');
    harness.handle_byte(b'"'"'y'"'"');

    assert_eq!(harness.ui().copied_text(), Some("Esc"));
}

#[test]
fn left_visual_starts_on_focused_control_row() {
    let mut harness = UiHarness::new(80, 24);
    assert_eq!(harness.ui().focus(), PaneFocus::Left);

    harness.handle_byte(b'"'"'v'"'"');
    harness.handle_byte(b'"'"'l'"'"');
    harness.handle_byte(b'"'"'l'"'"');
    harness.handle_byte(b'"'"'y'"'"');

    assert_eq!(harness.ui().copied_text(), Some(">us"));
}
EOF
CARGO_TARGET_DIR="${TMPDIR:-/tmp}/work-leaf-visual-repro-target" cargo test --manifest-path "$tmp/Cargo.toml" --test visual
